import{_ as s,H as a,f as n,i as t}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"02 | 一封迟到的信：怎样改变一个正在工作的Agent？","description":"","frontmatter":{},"headers":[{"level":2,"title":"一条告警，怎样进入正在运行的任务？","slug":"一条告警-怎样进入正在运行的任务","link":"#一条告警-怎样进入正在运行的任务","children":[]},{"level":2,"title":"告警会在哪一步生效？","slug":"告警会在哪一步生效","link":"#告警会在哪一步生效","children":[]},{"level":2,"title":"指令先到 Harness，再进入模型","slug":"指令先到-harness-再进入模型","link":"#指令先到-harness-再进入模型","children":[]},{"level":2,"title":"运行时新消息的四种去向","slug":"运行时新消息的四种去向","link":"#运行时新消息的四种去向","children":[]},{"level":2,"title":"转向也要等到模型能够重新判断","slug":"转向也要等到模型能够重新判断","link":"#转向也要等到模型能够重新判断","children":[]},{"level":2,"title":"中断也不会让时间倒流","slug":"中断也不会让时间倒流","link":"#中断也不会让时间倒流","children":[]},{"level":2,"title":"不同 Harness 把控制权放在哪里？","slug":"不同-harness-把控制权放在哪里","link":"#不同-harness-把控制权放在哪里","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"课后题：任选一题","slug":"课后题-任选一题","link":"#课后题-任选一题","children":[]}],"relativePath":"自进化Agent工程实战/02｜一封迟到的信：怎样改变一个正在工作的Agent？.md","filePath":"自进化Agent工程实战/02｜一封迟到的信：怎样改变一个正在工作的Agent？.md","lastUpdated":1795559729000}'),p={name:"自进化Agent工程实战/02｜一封迟到的信：怎样改变一个正在工作的Agent？.md"};function i(l,e,r,o,c,h){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="_02-一封迟到的信-怎样改变一个正在工作的agent" tabindex="-1">02 | 一封迟到的信：怎样改变一个正在工作的Agent？ <a class="header-anchor" href="#_02-一封迟到的信-怎样改变一个正在工作的agent" aria-label="Permalink to &quot;02 | 一封迟到的信：怎样改变一个正在工作的Agent？&quot;">​</a></h1><p>你好，我是 Tyler。</p><p>上一讲，我们把一项真实工作交给了 Harness。模型根据当前信息判断下一步，Harness 在环境中执行动作，再把得到的结果带回下一轮模型调用。如此循环下去，Agent 才能从一句任务要求出发，一步步查找资料、调用工具，最终形成可以检查的结果。</p><p>但任务一旦持续运行，新的问题就会出现：如果 Agent 已经开始工作，这时又来了一条新消息，它什么时候才会真正影响正在进行的任务？</p><h2 id="一条告警-怎样进入正在运行的任务" tabindex="-1">一条告警，怎样进入正在运行的任务？ <a class="header-anchor" href="#一条告警-怎样进入正在运行的任务" aria-label="Permalink to &quot;一条告警，怎样进入正在运行的任务？&quot;">​</a></h2><p>我们还是从一个 On-call Agent 开始。</p><p>没有故障时，它持续巡检高风险服务器，读取当前部署、最近的配置变更和监控指标。当它检</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>查到 server-17 时，已经知道这台机器正在运行 payment-api，凌晨一点四十分刚刚调整</span></span></code></pre></div><p>过数据库连接池。</p><p>凌晨两点零七分，一条告警到达：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server-17</span></span>
<span class="line"><span>payment-api P95 延迟超过 3 秒</span></span>
<span class="line"><span>错误率升至 8.4%</span></span></code></pre></div><p>这条告警没有重复服务器上的部署信息，也没有告诉 Agent 最近发生过什么变更。但这些背景，Agent 在刚才的巡检中已经拿到了。</p><p>所以，更合理的做法并不是重新启动一个什么都不知道的新 Agent，而是把这条告警直接交给正在工作的 Agent：让它利用已经掌握的信息，暂时从巡检转向故障调查，处理完以后再继续原来的任务。</p><p>问题是，告警到达 Harness 的那一刻，模型就会立即看到它吗？</p><p>不会。消息到达 Harness，与消息真正进入模型输入，是两个不同的时刻。这就是这一讲要讨论的“一封迟到的信”。</p><h2 id="告警会在哪一步生效" tabindex="-1">告警会在哪一步生效？ <a class="header-anchor" href="#告警会在哪一步生效" aria-label="Permalink to &quot;告警会在哪一步生效？&quot;">​</a></h2><p>上一讲我们已经看到，一项看起来连续运行的任务，实际上由模型调用和环境操作反复交替组成。</p><p>现在，把新的告警放进这条时间线。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/02/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/02/1.png" alt=""></a></p><ul><li>巡检中的告警何时进入正在运行的 Turn</li></ul><p>第一轮模型调用决定先查看高风险服务器列表。Harness 完成查询，把结果带入下一轮。模型</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>选中 server-17，决定读取它的部署和变更记录，于是 Harness 开始执行相应的工具调用。</span></span></code></pre></div><p>就在工具运行期间，告警到达了 Harness。</p><p>这时，刚才那轮模型调用已经结束，正在执行的读文件动作也已经发出。新告警不可能回到过去，改写已经结束的模型调用，也不能凭空改变一个已经发出的工具请求。</p><p>等部署和变更记录返回以后，Harness 才有机会把这份工具结果与刚刚收到的告警一起放进下一轮模型输入。</p><p>直到这个时候，模型才真正“看见”告警。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>它会发现，server-17 上运行的是 payment-api，连接池在二十多分钟前刚刚发生过调</span></span></code></pre></div><p>整，现在又出现了延迟和错误率异常。因为之前的巡检结果仍然保留在当前任务中，它不需要重新调查这些背景，就可以直接判断下一步应该检查什么。</p><p>这就是运行中转向真正有价值的地方：新的信息改变了接下来要做的事，但此前仍然有效的Context 和工作结果可以继续保留。</p><h2 id="指令先到-harness-再进入模型" tabindex="-1">指令先到 Harness，再进入模型 <a class="header-anchor" href="#指令先到-harness-再进入模型" aria-label="Permalink to &quot;指令先到 Harness，再进入模型&quot;">​</a></h2><p>为了把这个过程说清楚，需要先区分两个运行概念。</p><p>我们可以把 Thread 理解为一项持续工作的会话状态；Turn 则是其中一次由输入启动、持续执行直到结束的 Agent 运行。一个 Turn 内部仍然可能经历多轮模型判断、工具执行和结果返</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>回。Codex 当前的 Python SDK 也是以 Thread 保存会话状态，并通过 Thread.turn() 获</span></span></code></pre></div><p>得一个可以继续控制的活跃 Turn。</p><p>当一条新消息在 Turn 运行期间到达时，至少要解决三个问题：</p><ol><li><p>它属于哪个 Thread，又要影响哪个正在运行的 Turn？</p></li><li><p>它要改变当前工作，还是等当前工作结束以后再处理？</p></li><li><p>它从哪个位置开始进入后续判断？</p></li></ol><p>这三件事并不全部交给模型决定。告警内容是什么意思，由模型理解。它应该送到哪个Thread、是否要干预当前 Turn，则需要调用端和 Harness 明确指定。至于消息什么时候真正进入模型输入，还取决于 Agent 当时运行到了什么位置。</p><p>因此，一条自然语言指令其实回答了“要改什么”；Harness 的控制接口还要回答“改哪项任务，以及从什么时候开始影响它”。</p><p>这两个层次不能混在一起。</p><h2 id="运行时新消息的四种去向" tabindex="-1">运行时新消息的四种去向 <a class="header-anchor" href="#运行时新消息的四种去向" aria-label="Permalink to &quot;运行时新消息的四种去向&quot;">​</a></h2><p>一项任务运行几个小时以后，新消息会不断到达，但它们并不都应该立即改变当前工作。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我们可以先把运行时控制抽象成四种意图：queue、steer、interrupt 和 stop。这些词</span></span></code></pre></div><p>描述的是四种不同的控制目的，并不意味着所有 Harness 都提供完全同名的 API。</p><p>比如，你发来一句：巡检结束后，把今夜的高风险机器整理成早报。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这件事并不紧急，也不应该打断正在进行的巡检。最合适的处理方式是 queue：保留当前任</span></span></code></pre></div><p>务，把新工作放到后面。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>刚才的线上告警则不同。原来的巡检结果仍然有用，只是 server-17 的优先级突然变高。此</span></span>
<span class="line"><span>时更适合 steer：继续保留当前 Turn 中已经取得的信息，但修改接下来的工作方向。</span></span></code></pre></div><p>如果值班工程师随后发现，告警采集器的时间配置有误，当前调查正在基于错误数据不断向下</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>推进，就应该考虑 interrupt。它取消的是当前这次执行，让 Agent 不再沿着已经失效的方</span></span></code></pre></div><p>向继续工作。</p><p>还有一种情况更彻底。比如值班负责人要求暂停自动调查，等待现场确认，目前也没有新的执行方案。此时需要停止整个任务循环，不再继续调度新的动作。我们可以把这种生命周期层面</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>的控制称为 stop。</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/02/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/02/2.png" alt=""></a></p><ul><li>运行中消息的四种控制路径</li></ul><p>四种控制意图的区别可以概括为：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/02/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/02/3.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这里尤其要注意 interrupt 和 stop 的区别。</span></span>
<span class="line"><span>interrupt 通常仍然保留 Thread，你可以随后给出新的要求，再启动后续工作；stop 更接</span></span></code></pre></div><p>近任务或运行时生命周期控制，意思是暂时不要再继续执行。</p><p>具体产品怎样实现，还要看它自己的运行时设计。</p><h2 id="转向也要等到模型能够重新判断" tabindex="-1">转向也要等到模型能够重新判断 <a class="header-anchor" href="#转向也要等到模型能够重新判断" aria-label="Permalink to &quot;转向也要等到模型能够重新判断&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>steer 的目标是尽快改变正在运行的任务，但“尽快”并不意味着它可以回到过去。</span></span></code></pre></div><p>一条新指令无法修改已经结束的模型调用，也无法撤回已经产生的环境变化。真正有意义的问题是：Harness 下一次什么时候可以让模型重新判断？</p><p>在刚才的例子中，模型已经发出了读取服务器信息的动作。对于这种很快结束的只读操作，通常没有必要强行打断。等工具返回以后，把告警和工具结果一起交给模型，既保留了刚取得的信息，又能立即改变后续方向。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hermes 对这一点给出了非常明确的运行规则。它的 busy_input_mode 支持 queue、</span></span>
<span class="line"><span>steer 和 interrupt；其中 steer 会等待下一个工具结果边界再把新消息交给 Agent，默</span></span>
<span class="line"><span>认的 interrupt 可以在模型生成阶段更快响应，但不会直接取消一个已经运行起来的工</span></span>
<span class="line"><span>具。/stop 则用于取消当前 Turn 及其前台工作。</span></span>
<span class="line"><span>Codex 的控制接口采用了另一种表达方式。当前 Python SDK 中，Thread.turn() 会返回</span></span>
<span class="line"><span>TurnHandle，调用者可以通过 steer() 向正在运行的 Turn 追加输入，也可以通过</span></span>
<span class="line"><span>interrupt() 请求中断。App Server 对 turn/steer 的定义也很明确：它向一个已经处于</span></span></code></pre></div><p>运行状态的普通 Turn 增加新的用户输入，并不会另外创建一个 Turn。</p><p>至于这条输入具体在哪一个内部模型调用中开始发挥作用，不应该脱离具体运行事件凭空假设。调用端可以继续观察 Turn 的事件流，判断 Agent 后续采取的动作是否已经受到新指令影响。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>因此，steer 更准确的理解是：修改一个仍在运行的任务接下来怎样继续，而不是修改它刚</span></span></code></pre></div><p>才已经做过什么。</p><h2 id="中断也不会让时间倒流" tabindex="-1">中断也不会让时间倒流 <a class="header-anchor" href="#中断也不会让时间倒流" aria-label="Permalink to &quot;中断也不会让时间倒流&quot;">​</a></h2><p>这里还有一个非常重要的边界。假设 Agent 已经修改了配置文件，然后你才发出</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>interrupt。</span></span></code></pre></div><p>中断当前 Turn，并不会自动把文件恢复到修改前。</p><p>同样，如果 Agent 已经向外部系统提交了请求，已经启动了一个进程，或者已经完成了一次数据库写入，那么终止后续推理也不会让这些副作用自动消失。</p><p>所以，运行控制和状态回滚是两件不同的事。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Harness 可以通过 interrupt 或其他机制阻止后续动作；已经发生的环境变化，则需要</span></span></code></pre></div><p>Git、文件快照、数据库事务、幂等设计或补偿操作来恢复。这一点在设计长程 Agent 时非常重要。能“停下来”，并不代表能“回到原来的状态”。</p><h2 id="不同-harness-把控制权放在哪里" tabindex="-1">不同 Harness 把控制权放在哪里？ <a class="header-anchor" href="#不同-harness-把控制权放在哪里" aria-label="Permalink to &quot;不同 Harness 把控制权放在哪里？&quot;">​</a></h2><p>理解了这些控制意图以后，再去看 Codex、Hermes、Claude Code 或 OpenCode，就不容易被具体产品的动作命名带偏。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/02/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/02/4.png" alt=""></a></p><p>Hermes 的这些行为由当前 CLI 文档直接定义；Codex Python SDK 和 App Server 也明确暴</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>露了同 Turn 的 steering 与 interrupt。Claude Code 当前文档说明，Esc 可以在 Turn 中停止</span></span>
<span class="line"><span>当前响应或工具调用，并保留已经完成的工作，而 /btw 在主任务运行时独立回答旁路问题，</span></span></code></pre></div><p>不会干扰主 Turn。OpenCode Server 则明确提供异步消息发送和 Session abort，但其文档没有进一步承诺异步消息一定具备“当前活跃 Turn steering”的语义。</p><p>这些 API 和默认行为以后都可能变化。真正稳定的问题始终只有三个：这条消息属于哪项工作？它选择了哪种控制意图？它从什么时候开始影响后续行为？</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>学到这里，我们回头看一下这封“迟到的信”。</p><p>告警在凌晨两点零七分已经到达 Harness，但那一刻并不代表模型已经看到它。只有当Harness 把它放进后续的模型输入，它才真正成为 Agent 判断的一部分。于是，运行中的消息出现了几种不同去向。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>queue 把新工作放到当前任务之后；steer 保留仍然有效的 Context 和进展，只改变接下来</span></span>
<span class="line"><span>要做什么；interrupt 结束已经失效的当前 Turn；stop 则进一步停止任务循环或后续调</span></span></code></pre></div><p>度。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/02/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/02/5.png" alt=""></a></p><p>它们共同解决的问题是：环境已经发生变化，但我们不希望每发生一次变化，就把整个任务推倒重来。</p><p>这也是为什么运行时干预很像一次 Hotfix。真正好的干预，不是重新接管 Agent 的每一个步骤，而是在现实世界偏离原计划时，尽可能保留仍然有效的部分，只修正已经失效的方向。</p><p>这种思想也并不是新事物。在经典自动规划研究中，Plan Repair 讨论的就是类似问题。当执行环境或目标发生变化以后，可以完全重新规划，也可以尽量在原计划基础上进行修复。对今天的长程 Agent 来说，同样的问题重新出现了。</p><p>只不过过去我们修的是 Plan，现在还要同时考虑已经积累的 Context、完成的工具操作、形成的中间结果，以及 Agent 对外部环境已经产生的影响。</p><h2 id="课后题-任选一题" tabindex="-1">课后题：任选一题 <a class="header-anchor" href="#课后题-任选一题" aria-label="Permalink to &quot;课后题：任选一题&quot;">​</a></h2><p>思考题：为什么运行时干预要遵循最小变更原则？</p><p>2006 年的《Plan Stability: Replanning versus Plan Repair》讨论了一个很有意思的问题：当环境或目标发生变化以后，我们可以从头重新规划，也可以尽量保留原有计划中仍然有效的部分，只修改无法继续执行的部分。论文把这种对原计划扰动程度的关注称为 Plan Stability。</p><p>长程 Agent 面临着类似的问题。一条运行中的指令如果改变得太少，可能无法应对新的环境；如果直接推倒重来，又可能丢掉已经取得的 Context、中间结果，甚至破坏此前已经形成的外部承诺。</p><p>为什么对长程 Agent 的运行时干预，也应该像 Hotfix 一样遵循最小变更原则？</p><p>观察题：让巡检 Agent 转入 On-call</p><p>打开 Github 中的随讲实验 Notebook，从第一个单元格开始依次运行。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Notebook 会先启动一个巡检 Turn。Agent 读取 server-17 的部署和变更记录以后，一条只</span></span>
<span class="line"><span>包含服务器、时间和异常现象的告警会通过 TurnHandle.steer() 进入同一个正在运行的</span></span>
<span class="line"><span>Turn。Codex 当前 Python SDK 明确提供 turn()、steer() 和 interrupt() 这组低层控</span></span></code></pre></div><p>制接口。</p><p>任务结束以后，请重点检查四件事：告警是否进入了原来的 Turn；故障调查是否使用了告警到达以前已经取得的变更信息；Agent 是否按照任务要求继续后续工作；无关文件是否保持不变。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Notebook 后半部分还会通过一个没有副作用的慢任务演示 interrupt()。你可以直接比</span></span>
<span class="line"><span>较：steer 修改的是一个任务接下来怎样继续，而 interrupt 则结束当前这次执行。</span></span></code></pre></div><p>期待你在留言区记录想法或者提出疑问，如果今天的内容对你有帮助，别忘了分享给身边更多朋友。</p>`,105)])])}const u=s(p,[["render",i]]);export{g as __pageData,u as default};
